mapper.select:
SELECT so.id, so.outbound_no, so.platform, so.warehouse_id, so.outbound_date, so.order_count, so.sku_count, so.total_quantity, so.order_status, so.remark, so.create_by, so.create_time FROM wms_sales_outbound_order so
AND so.source_type = 'SALES'
AND so.outbound_no LIKE CONCAT('%', #{qo.outboundNo}, '%')
AND so.platform = #{qo.platform}
AND EXISTS ( SELECT 1 FROM wms_sales_outbound_order_item soi WHERE soi.outbound_order_id = so.id AND soi.platform_order_id LIKE CONCAT('%', #{qo.platformOrderId}, '%') )
AND so.warehouse_id = #{qo.warehouseId}
AND so.order_status = #{qo.orderStatus}
AND so.outbound_date >= #{qo.outboundDateStart}
AND so.outbound_date <= #{qo.outboundDateEnd}
ORDER BY so.create_time DESC

SELECT so.id, so.outbound_no, so.platform, so.warehouse_id, so.outbound_date, so.order_count, so.sku_count, so.total_quantity, so.order_status, so.remark, so.create_by, u.nickname AS create_by_name, so.create_time FROM wms_sales_outbound_order so LEFT JOIN sys_user u ON so.create_by = u.user_id
AND so.source_type = 'SALES'
AND so.outbound_no LIKE CONCAT('%', #{qo.outboundNo}, '%')
AND so.platform = #{qo.platform}
AND EXISTS ( SELECT 1 FROM wms_sales_outbound_order_item soi WHERE soi.outbound_order_id = so.id AND soi.platform_order_id LIKE CONCAT('%', #{qo.platformOrderId}, '%') )
AND so.warehouse_id = #{qo.warehouseId}
AND so.order_status = #{qo.orderStatus}
AND so.outbound_date >= #{qo.outboundDateStart}
AND so.outbound_date <= #{qo.outboundDateEnd}
ORDER BY so.create_time DESC
